export function binaryTreeMaximumPathSum(values                 )         {
                                       function build(a                )        {if(!a.length||a[0]===null)return null;const root  ={v:a[0],l:null,r:null},q    =[root];let i=1;for(let j=0;j<q.length&&i<a.length;j++){for(const key of ['l','r']         ){const v=a[i++];if(v!==null&&v!==undefined){const n  ={v,l:null,r:null};q[j][key]=n;q.push(n);}}}return root;}let best=-Infinity;function gain(n       )       {if(!n)return 0;const l=Math.max(0,gain(n.l)),r=Math.max(0,gain(n.r));best=Math.max(best,n.v+l+r);return n.v+Math.max(l,r);}gain(build(values));return best;
}

