type N = {v:number,l:N|null,r:N|null}; function build(a:(number|null)[]):N|null {if(!a.length||a[0]===null)return null;const root:N={v:a[0],l:null,r:null},q:N[]=[root];let i=1;for(let j=0;j<q.length&&i<a.length;j++){for(const key of ['l','r'] as const){const v=a[i++];if(v!==null&&v!==undefined){const n:N={v,l:null,r:null};q[j][key]=n;q.push(n);}}}return root;}let best=-Infinity;function gain(n:N|null):number{if(!n)return 0;const l=Math.max(0,gain(n.l)),r=Math.max(0,gain(n.r));best=Math.max(best,n.v+l+r);return n.v+Math.max(l,r);}gain(build(values));return best;
}
